import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "react-toastify";

const SellerApplyForReels = ({ onClose }) => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    mobile: "",
    companyName: "",
    companyWebsite: "",
    instagramHandle: "",
    facebookPage: "",
    experience: "",
    categories: "",
    message: ""
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);
  const [showPasswordForm, setShowPasswordForm] = useState(false);
  const [passwordData, setPasswordData] = useState({
    password: "",
    confirmPassword: ""
  });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handlePasswordChange = (e) => {
    setPasswordData({
      ...passwordData,
      [e.target.name]: e.target.value
    });
  };

  const validateForm = () => {
    if (!formData.firstName || !formData.lastName || !formData.email || !formData.mobile) {
      setError("First Name, Last Name, Email, and Mobile Number are required");
      return false;
    }
    return true;
  };

  const validatePasswordForm = () => {
    if (!passwordData.password || !passwordData.confirmPassword) {
      setError("Please enter and confirm your password");
      return false;
    }
    if (passwordData.password !== passwordData.confirmPassword) {
      setError("Passwords do not match");
      return false;
    }
    if (passwordData.password.length < 6) {
      setError("Password must be at least 6 characters");
      return false;
    }
    return true;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!validateForm()) return;

    setLoading(true);
    setError("");

    try {
      // Check if seller exists in oc_vendor table
      const response = await fetch("/api/Studio/seller/check-details", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          email: formData.email,
          mobile: formData.mobile,
          firstName: formData.firstName,
          lastName: formData.lastName
        }),
      });

      const result = await response.json();

      if (response.ok) {
        // Seller exists in oc_vendor table
        if (result.exists) {
          // Show password form
          setShowPasswordForm(true);
        } else {
          // Seller does not exist
          setError("You are not a seller of IPShopy. Please first register as a seller.");
        }
      } else {
        setError(result.message || "An error occurred while checking seller details");
      }
    } catch (err) {
      setError("Network error. Please try again.");
      console.error("Error:", err);
    } finally {
      setLoading(false);
    }
  };

  const handlePasswordSubmit = async (e) => {
    e.preventDefault();
    
    if (!validatePasswordForm()) return;

    setLoading(true);
    setError("");

    try {
      // Register seller with password
      const response = await fetch("/api/Studio/seller/register-for-reels", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          ...formData,
          password: passwordData.password
        }),
      });

      const result = await response.json();

      if (response.ok) {
        setSuccess(true);
        toast.success("Registration successful! You can now login.");
        setTimeout(() => {
          onClose();
          navigate("/studio/seller-dashboard");
        }, 2000);
      } else {
        setError(result.message || "Registration failed");
      }
    } catch (err) {
      setError("Network error. Please try again.");
      console.error("Error:", err);
    } finally {
      setLoading(false);
    }
  };

  if (success) {
    return (
      <div className="text-center py-5">
        <div className="text-success mb-3">
          <i className="fas fa-check-circle fa-3x"></i>
        </div>
        <h4>Application Submitted Successfully!</h4>
        <p>Your application for reels has been submitted. We'll review it shortly.</p>
      </div>
    );
  }

  return (
    <div>
      {showPasswordForm ? (
        // Password Form
        <form onSubmit={handlePasswordSubmit}>
          <div className="mb-3">
            <label className="form-label">Set Password *</label>
            <input
              type="password"
              className="form-control"
              name="password"
              value={passwordData.password}
              onChange={handlePasswordChange}
              placeholder="Enter password"
              required
            />
          </div>
          <div className="mb-3">
            <label className="form-label">Confirm Password *</label>
            <input
              type="password"
              className="form-control"
              name="confirmPassword"
              value={passwordData.confirmPassword}
              onChange={handlePasswordChange}
              placeholder="Confirm password"
              required
            />
          </div>
          
          {error && <div className="alert alert-danger">{error}</div>}
          
          <div className="d-flex justify-content-between">
            <button
              type="button"
              className="btn btn-secondary"
              onClick={() => setShowPasswordForm(false)}
              disabled={loading}
            >
              Back
            </button>
            <button
              type="submit"
              className="btn btn-primary"
              disabled={loading}
            >
              {loading ? "Processing..." : "Register"}
            </button>
          </div>
        </form>
      ) : (
        // Application Form
        <form onSubmit={handleSubmit}>
          <div className="row">
            <div className="col-md-6 mb-3">
              <label className="form-label">First Name *</label>
              <input
                type="text"
                className="form-control"
                name="firstName"
                value={formData.firstName}
                onChange={handleChange}
                placeholder="Enter your first name"
                required
              />
            </div>
            <div className="col-md-6 mb-3">
              <label className="form-label">Last Name *</label>
              <input
                type="text"
                className="form-control"
                name="lastName"
                value={formData.lastName}
                onChange={handleChange}
                placeholder="Enter your last name"
                required
              />
            </div>
          </div>
          
          <div className="mb-3">
            <label className="form-label">Email Address *</label>
            <input
              type="email"
              className="form-control"
              name="email"
              value={formData.email}
              onChange={handleChange}
              placeholder="Enter your email"
              required
            />
          </div>
          
          <div className="mb-3">
            <label className="form-label">Mobile Number *</label>
            <input
              type="tel"
              className="form-control"
              name="mobile"
              value={formData.mobile}
              onChange={handleChange}
              placeholder="Enter your mobile number"
              required
            />
          </div>
          
          <div className="mb-3">
            <label className="form-label">Company Name</label>
            <input
              type="text"
              className="form-control"
              name="companyName"
              value={formData.companyName}
              onChange={handleChange}
              placeholder="Enter your company name"
            />
          </div>
          
          <div className="mb-3">
            <label className="form-label">Company Website</label>
            <input
              type="url"
              className="form-control"
              name="companyWebsite"
              value={formData.companyWebsite}
              onChange={handleChange}
              placeholder="https://example.com"
            />
          </div>
          
          <div className="row">
            <div className="col-md-6 mb-3">
              <label className="form-label">Instagram Handle</label>
              <input
                type="text"
                className="form-control"
                name="instagramHandle"
                value={formData.instagramHandle}
                onChange={handleChange}
                placeholder="@username"
              />
            </div>
            <div className="col-md-6 mb-3">
              <label className="form-label">Facebook Page</label>
              <input
                type="text"
                className="form-control"
                name="facebookPage"
                value={formData.facebookPage}
                onChange={handleChange}
                placeholder="Page URL"
              />
            </div>
          </div>
          
          <div className="mb-3">
            <label className="form-label">Experience</label>
            <textarea
              className="form-control"
              name="experience"
              value={formData.experience}
              onChange={handleChange}
              rows="3"
              placeholder="Describe your experience"
            ></textarea>
          </div>
          
          <div className="mb-3">
            <label className="form-label">Categories</label>
            <input
              type="text"
              className="form-control"
              name="categories"
              value={formData.categories}
              onChange={handleChange}
              placeholder="Enter categories"
            />
          </div>
          
          <div className="mb-3">
            <label className="form-label">Message</label>
            <textarea
              className="form-control"
              name="message"
              value={formData.message}
              onChange={handleChange}
              rows="3"
              placeholder="Any additional information"
            ></textarea>
          </div>
          
          {error && <div className="alert alert-danger">{error}</div>}
          
          <div className="d-flex justify-content-between">
            <button
              type="button"
              className="btn btn-secondary"
              onClick={onClose}
            >
              Cancel
            </button>
            <button
              type="submit"
              className="btn btn-primary"
              disabled={loading}
            >
              {loading ? "Checking..." : "Submit Application"}
            </button>
          </div>
        </form>
      )}
    </div>
  );
};

export default SellerApplyForReels;
